var n=`0672-kenkey`;var i=`world-0672`;var a=`GH`;var o=`western-africa`;var r=8;var s=822;var l={en:`Kenkey`,ua:`Кенкей`};var d={en:`Kenkey is a Ghana classic prepared with cornmeal, sourdough starter, tilapia, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Homemade kenkey-style fermented corn dough; fermentation and wrapping differ from traditional methods. Tilapia is grilled separately.`,ua:`Кенкей, страва кухні країни Гана зі складниками: кукурудзяна крупа дрібного помелу, хлібна закваска, тилапія, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Домашнє тісто у стилі кенкею; ферментація й загортання відрізняються від традиційних. Тіляпію готують окремо на грилі.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:14,i:[[`cornmeal`,420,`g`],[`water`,570,`ml`],[`sourdough-starter`,55,`g`],[`table-salt`,4,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 720 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 720 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:720,i:[]},{en:`Divide the fermented corn dough into portions wrapped in heatproof food-safe leaves or parchment and steam until thoroughly set.`,ua:`Розділіть ферментоване кукурудзяне тісто на порції, загорніть у придатне для нагрівання харчове листя чи пергамент і пропарте до повної готовності.`,t:[`basket-steaming`],m:55,i:[]},{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 15 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 15 хвилин.`,t:[`marinating`],m:15,i:[[`tilapia`,550,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`lemon-juice`,30,`ml`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[[`sunflower-oil`,25,`ml`]]}];var u={slug:n,id:i,country:`GH`,region:o,servings:8,minutes:822,title:l,text:d,steps:m};export{a as country,u as default,i as id,s as minutes,o as region,r as servings,n as slug,m as steps,d as text,l as title};